/* AniMus shared show gallery */
.musical-project-gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(235px,1fr));gap:15px;margin:1em 0}
.musical-project-card{border:1px solid #b6c6d9;border-radius:12px;padding:18px;background:linear-gradient(140deg,#f3f8fd,#fff);color:#23384c}
.musical-project-card h2{margin:0 0 .55em;font-size:1.3em}
.musical-project-card a{display:inline-block;background:#146b81;color:white!important;border-radius:6px;padding:8px 12px;text-decoration:none;font-weight:600}
@media(max-width:620px){.musical-project-gallery{grid-template-columns:1fr}}
